["description"] = "Vence en todos los encuentros además de derrotar a la verdugo Jerensi, al brujo supremo Vandorallen y a Borrasca de Retribución en el Reducto de los Exiliados (Veterano) en menos de 25 minutos. El temporizador comienza al entablar combate con el primer grupo de enemigos.",
