}
,
[4113] = {
["description"] = "Vence en todos los encuentros además de derrotar a la verdugo Jerensi, al brujo supremo Vandorallen y a Borrasca de Retribución en el Reducto de los Exiliados (Veterano) sin que ningún miembro del grupo muera.",
