,
[4115] = {
["description"] = "Vence en todos los encuentros además de derrotar a la verdugo Jerensi, al brujo supremo Vandorallen y a Borrasca de Retribución tras colocar el estandarte del desafío en el Reducto de los Exiliados (Veterano) en 25 minutos sin que ningún miembro del grupo muera. El temporizador comienza al entablar combate con el primer grupo de enemigos.",
["name"] = "Rompedor de venganzas",
}
,
