}
,
[4117] = {
["description"] = "Durante la batalla contra Borrasca de Retribución, recoge un orbe de fuego, de hielo o de descarga eléctrica antes de que evolucionen a erupción ardiente, fragmento congelante o relámpago explosivo y derrota a Borrasca de Retribución en el Reducto de los Exiliados.",
["name"] = "Sin fragmentar",
}
,
[4120] = {
["description"] = "Tras izar el estandarte del desafío en un grupo completo de 4 jugadores, derrota a Borrasca de Retribución después de que todos los miembros de tu grupo hayan obtenido un orbe elemental de cada color en el Reducto de los Exiliados (Veterano).",
["name"] = "Exposición a los elementos",
}
,
[4121] = {
["description"] = "En una expedición al Reducto de los Exiliados, derrota al capitán de la guardia Paracio, al docente Domicio y a Eliana Albo antes de derrotar a Borrasca de Retribución.",
["name"] = "Regreso al descanso",
}
,
