["name"] = "Conquistador de la Guarida de los Colmillos",
}
,
[1963] = {
["description"] = "Vence en todos los encuentros y derrota a Lizabet Charnis, a la colección de animales cadavéricos, a Caluurion, a Ulfnor y Sabina Cedo y a Orryn el Negro y Thurvokun en la Guarida de los Colmillos (Veterano) en menos de 30 minutos. El temporizador comienza cuando los jugadores atacan al primer grupo de nigromantes de la Médula Negra.",
