["name"] = "Ponle un tapón",
}
,
[2101] = {
["description"] = "Derrota a todos los jefes que puedan aparecer en los géiseres abisales.",
["name"] = "Regreso al abismo",
}
,
[2102] = {
["description"] = "Vence en todos los encuentros y derrota a Lizabet Charnis, a la colección de animales cadavéricos, a Caluurion, a Ulfnor y Sabina Cedo, además de a Orryn el Negro y Thurvokun en el modo difícil de la Guarida de los Colmillos (Veterano) en menos de 30 minutos sin que ningún miembro del grupo muera. El temporizador comienza al entablar combate con el primer grupo de nigromantes de la Médula Negra.",
["name"] = "Ningún hueso sin romper",
}
,
[2103] = {
["description"] = "Completa la Guarida de los Colmillos y la Cumbre de la Invocadora de Escamas (Veterano).",
["name"] = "Espeleólogo de Dragon Bones",
}
,
[2131] = {
["description"] = "Derrota a Z\'Maja, Siroria, Relequen y a Galenwe en Nubelia.",
["name"] = "Nubelia completada",
}
,
[2132] = {
["description"] = "Derrota a Z\'Maja, Siroria, Relequen y a Galenwe en el mismo combate en Nubelia.",
["name"] = "Contendiente de Nubelia",
}
,
[2133] = {
["description"] = "Derrota a Z\'Maja, Siroria, Relequen y a Galenwe en Nubelia (Veterano).",
["name"] = "Conquistador de Nubelia",
}
,
[2134] = {
["description"] = "Derrota a Z\'Maja con un welkynar sombrío luchando a su lado en Nubelia (Veterano).",
["name"] = "Una sload y su sombra",
}
,
[2135] = {
["description"] = "Derrota a Z\'Maja con dos welkynar sombríos luchando a su lado en Nubelia (Veterano).",
["name"] = "La compañía del trío mortal",
}
,
[2136] = {
["description"] = "Derrota a Z\'Maja, a Siroria, a Relequen y a Galenwe en el mismo combate en Nubelia (Veterano).",
["name"] = "Vencedor de Nubelia",
}
,
[2137] = {
["description"] = "Derrota a Z\'Maja, a Siroria, a Relequen y a Galenwe en menos de 15 minutos en Nubelia (Veterano). El temporizador comienza cuando los jugadores entran en el Nido de Nubelia.",
["name"] = "Erradicador veloz de sload",
}
,
[2138] = {
["description"] = "Derrota a Z\'Maja, a Siroria, a Relequen y a Galenwe sin que ningún miembro del grupo muera en Nubelia (Veterano).",
["name"] = "Sobrevivir a las sombras",
}
,
[2139] = {
["description"] = "Derrota a Z\'Maja, a Siroria, a Relequen y a Galenwe en el mismo combate sin que ningún miembro del grupo muera y en menos de 15 minutos desde la entrada al Nido de Nubelia en Nubelia (Veterano).",
["name"] = "El Sendero de Alaxon",
}
,
[2140] = {
["description"] = "Completa los siguientes logros en Nubelia.",
["name"] = "Salvador de Nubelia",
}
,
[2152] = {
["description"] = "Derrota al carcelero Melito, al guardián del laberinto, a Mylenne Aúlla Lunas, al archivista Ernarde y a Vykosa la Ascendida en el Bastión del Cazador de la Luna.",
["name"] = "Vencedor del Bastión del Cazador de la Luna",
}
,
[2153] = {
["description"] = "Derrota al carcelero Melito, al guardián del laberinto, a Mylenne Aúlla Lunas, al archivista Ernarde y a Vykosa la Ascendida en el Bastión del Cazador de la Luna (Veterano).",
["name"] = "Conquistador del Bastión del Cazador de la Luna",
}
,
[2154] = {
["description"] = "Derrota al Vykosa la Ascendida en el Bastión del Cazador de la Luna (Veterano) tras invocar el pergamino de la gloriosa batalla.",
["name"] = "Depredador alfa",
}
,
[2155] = {
["description"] = "Vence en todos los encuentros además de al carcelero Melito, al guardián del laberinto, a Mylenne Aúlla Lunas, al archivista Ernarde y a Vykosa la Ascendida en el Bastión del Cazador de la Luna (Veterano) en menos de 30 minutos. El temporizador comienza cuando los jugadores atacan al primer grupo de enemigos del Cazador de la Luna.",
["name"] = "Corriendo con la manada",
}
,
[2156] = {
["description"] = "Vence en todos los encuentros además de al carcelero Melito, al guardián del laberinto, a Mylenne Aúlla Lunas, al archivista Ernarde y a Vykosa la Ascendida en el Bastión del Cazador de la Luna (Veterano) y sin que ningún miembro del grupo muera.",
["name"] = "Jefe de la manada",
}
,
[2158] = {
["description"] = "Completa los siguientes logros en el Bastión del Cazador de la Luna (Veterano).",
["name"] = "Contendiente del Bastión del Cazador de la Luna",
}
,
[2159] = {
["description"] = "Vence en todos los encuentros y derrota al carcelero Melito, al guardián del laberinto, a Mylenne Aúlla Lunas, al archivista Ernarde y a Vykosa la Ascendida después de activar el modo difícil en el Bastión del Cazador de la Luna (Veterano) en menos de 30 minutos sin que ningún miembro del grupo muera. El temporizador comienza al entablar combate con el primer grupo de enemigos del Cazador de la Luna.",
["name"] = "Auténtica locura",
}
,
[2162] = {
["description"] = "Derrota a las hermanas del wyrd, a Aghaedh del Solsticio, a Dagrund el Rechoncho, a Tarcyr y a Balorgh en Marcha de los Sacrificios.",
["name"] = "Vencedor de la Marcha de los Sacrificios",
}
,
[2163] = {
["description"] = "Derrota a las hermanas del wyrd, a Aghaedh del Solsticio, a Dagrund el Rechoncho, a Tarcyr y a Balorgh en Marcha de los Sacrificios (Veterano).",
["name"] = "Conquistador de la Marcha de los Sacrificios",
}
,
[2164] = {
["description"] = "Derrota a Balorgh después de haber profanado el estandarte de la Manada del Cazador de la Luna y haberle provocado una rabia asesina en la Marcha de los Sacrificios (Veterano).",
["name"] = "Campeón de Hircine",
}
,
[2165] = {
["description"] = "Vence en todos los encuentros y además derrota a las hermanas del wyrd, a Aghaedh del Solsticio, a Dagrund el Rechoncho, a Tarcyr y a Balorgh en Marcha de los Sacrificios (Veterano) en menos de 35 minutos. El temporizador comienza cuando los jugadores salten o se teletransporten al Paso de los Rastreadores.",
["name"] = "Instinto puro",
}
,
[2166] = {
["description"] = "Vence en todos los encuentros y además derrota a las hermanas del wyrd, a Aghaedh del Solsticio, a Dagrund el Rechoncho, a Tarcyr y a Balorgh en Marcha de los Sacrificios (Veterano) sin que ningún miembro del grupo muera.",
["name"] = "La supervivencia del más fuerte",
}
,
[2167] = {
["description"] = "Completa los siguientes logros en la Marcha de los Sacrificios (Veterano).",
["name"] = "Contendiente de la Marcha de los Sacrificios",
}
,
[2168] = {
["description"] = "Vence en todos los encuentros y derrota a las hermanas del wyrd, a Aghaedh del Solsticio, a Dagrund el Rechoncho, a Tarcyr y a Balorgh tras profanar el estandarte de la Manada del Cazador de la Luna en la Marcha de los Sacrificios (Veterano) en menos de 30 minutos sin que ningún miembro del grupo muera. El temporizador comienza al entrar en el Paso de los Rastreadores.",
["name"] = "Depredador extremo",
}
,
[2170] = {
["description"] = "Completa el Bastión del Cazador de la Luna (Veterano) y la Marcha de los Sacrificios (Veterano).",
["name"] = "Espeleólogo de Wolfhunter",
}
,
[2171] = {
["description"] = "Completa la investigación del alguacil Naramin sobre Choixth.",
["name"] = "Un libro y su portada",
}
,
[2181] = {
["description"] = "Derrota a tres campeones de Karnwasten.",
["name"] = "Vencedor de Karnwasten",
}
,
[2182] = {
["description"] = "Derrota a tres campeones de Solaria.",
["name"] = "Vencedor de Solaria",
}
,
[2184] = {
["description"] = "Derrota a Ruella Muchas-Garras en un géiser abisal.",
["name"] = "Sin garras",
}
,
[2185] = {
["description"] = "Derrota a Churug del Abismo en un géiser abisal.",
["name"] = "Pena de Churug",
}
,
[2193] = {
["description"] = "Completa misiones, derrota a jefes y explora cuevas para convertirte en el salvador de Estivalia.",
["name"] = "Salvador de Estivalia",
}
,
[2194] = {
["description"] = "Detén la conspiración que está sumiendo en el caos a Estivalia, protege la Torre de Cristal y forja una nueva alianza para restaurar el orden en las islas.",
["name"] = "Por el bien común",
}
,
[2203] = {
["description"] = "Completa la misión «Recuerdos enterrados».",
["name"] = "Juegos mentales",
}
,
[2206] = {
["description"] = "Completa la misión «Pérdida de sentido».",
["name"] = "Un narrador poco fiable",
}
,
[2208] = {
["description"] = "Completa la misión «La Torre de Cristal».",
["name"] = "Lo que se tiene que hacer",
}
,
[2212] = {
["description"] = "Derrota a Rompedor de Quillas sin pisar ninguna serpiente.",
["name"] = "Conocimiento serpentino",
}
,
[2213] = {
["description"] = "Derrota a Sheefar de las profundidades en un géiser abisal.",
["name"] = "Hacia las profundidades",
}
,
[2220] = {
["description"] = "Derrota a Girawell la Errática en un géiser abisal.",
["name"] = "Sereno y calculador",
}
,
[2221] = {
["description"] = "Derrota a Muustikar Tragón de olas en un géiser abisal.",
["name"] = "Rompeolas",
}
,
[2222] = {
["description"] = "Derrota a Martillo Arrecife en un géiser abisal.",
["name"] = "Entre el clavo y el martillo",
}
,
[2231] = {
["description"] = "Derrota a Z\'Maja con cada miembro del grupo recogiendo y destruyendo solo un núcleo malévolo en Nubelia (Veterano).",
["name"] = "Un corazón, a la sazón",
}
,
[2232] = {
["description"] = "Mientras te enfrentas a Z\'Maja con los tres welkynar sombríos a su lado, un jugador con la aflicción de escarcha y otros dos con la aflicción de sobrecarga voltaica comparten el daño de la erupción de Llama rugiente en Nubelia (Veterano).",
["name"] = "Compañía en la miseria",
}
,
[2233] = {
["description"] = "Mientras luchas contra Z\'Maja con la sombra de Siroria a su lado, utiliza un ataque Llama rugiente y propina 20 golpes mortales a las Sombras de los Difuntos en Nubelia (Veterano).",
["name"] = "Fulgores y sombras mortales",
}
,
[2234] = {
["description"] = "Mientras te enfrentas a Z\'Maja, tras activar una Luz del welkynar, activa dos más y destruye tres núcleos malévolos en menos de 6 segundos en Nubelia (Veterano).",
["name"] = "Coordinación central",
}
,
[2235] = {
["description"] = "Mientras te enfrentas a Z\'Maja, durante un evento de Mundo de las sombras, evita que todos los yaghra atraviesen el portal y alcancen el reino mortal en 15 ocasiones diferentes en Nubelia.",
["name"] = "Barrera de yaghra",
}
,
[2236] = {
["description"] = "Haz que la sombra de Galenwe destruya 20 ciclones de escarcha móviles con su ataque Pinchos de hielo en Nubelia.",
["name"] = "El hielo del místico",
}
,
[2237] = {
["description"] = "Mientras lucháis contra la sombra de Relequen sola, Sobrecarga voltaica no debe alcanzar a ningún jugador y ninguno debe propagar Corriente voltaica a otros jugadores durante todo el encuentro en Nubelia.",
["name"] = "Instinto de choque",
}
,
[2238] = {
["description"] = "Mientras lucháis contra la sombra de Siroria sola, cada Llama rugiente del encuentro debe dividirse entre al menos entre 6 jugadores en Nubelia.",
["name"] = "Combustión valiente",
}
,
[2241] = {
["description"] = "Derrota a Tormenta Oscura la Seductora en un géiser abisal.",
["name"] = "Carnada mortal",
}
,
[2242] = {
["description"] = "Derrota a Eejoba la Radiante en un géiser abisal.",
["name"] = "Revuelta fulgurante",
}
,
[2243] = {
["description"] = "Derrota a Maremoto en un géiser abisal.",
["name"] = "De la marea a la tumba",
}
,
[2244] = {
["description"] = "Derrota a Vsskalvor en un géiser abisal.",
["name"] = "Encantador de serpientes",
}
,
[2249] = {
["description"] = "Completa la misión de la Orden Psijic «La llamada de los psijic» en Estivalia.",
["name"] = "Corresponsal psijic",
}
,
[2250] = {
["description"] = "Completa la misión de la Orden Psijic «Fisuras en la bahía» en Estivalia.",
["name"] = "Rastreador psijic",
}
,
[2251] = {
["description"] = "Completa la misión «Incumplimientos de fuego y hielo» de la Orden Psijic en Estivalia.",
["name"] = "Regulador psijic",
}
,
[2252] = {
["description"] = "Completa la misión «El bastón roto» de la Orden Psijic en Estivalia.",
["name"] = "Reparador psijic",
}
,
[2253] = {
["description"] = "Completa la misión de la Orden Psijic «Una brecha en medio de los árboles» en Estivalia.",
["name"] = "Guardabosques psijic",
}
,
[2254] = {
["description"] = "Completa la misión «El tiempo del barro y las setas» de la Orden Psijic en Estivalia.",
["name"] = "Difamador psijic",
}
,
[2255] = {
["description"] = "Completar la misión «Los restos de las torres» de la Orden Psijic en Estivalia.",
["name"] = "Descubridor del báculo psijic",
}
,
[2256] = {
["description"] = "Completa la misión «Un tiempo a la sombra de Risco de la Perdición» de la Orden Psijic en Estivalia.",
["name"] = "Caminante entre sombras psijic",
}
,
[2257] = {
["description"] = "Completa la misión «Una brecha bajo las rocas» de la Orden Psijic en Estivalia.",
["name"] = "Cronólogo psijic",
}
,
[2260] = {
["description"] = "Derrota al Acechador del Hielo, al señor de la guerra Tzogvin, al protector de la cámara, a Rizzuk el Escalofriante y al guardián de la tablilla en la Cripta Helada.",
["name"] = "Vencedor de la Cripta Helada",
}
,
[2261] = {
["description"] = "Derrota al Acechador del Hielo, al señor de la guerra Tzogvin, al protector de la cámara, a Rizzuk el Escalofriante y al guardián de la tablilla en la Cripta Helada (Veterano).",
["name"] = "Conquistador de la Cripta Helada",
}
,
[2262] = {
["description"] = "Derrota al guardián de la tablilla tras activar el verificador de veracidad en la Cripta Helada (Veterano).",
["name"] = "Ladrón de cámaras",
}
,
[2263] = {
["description"] = "Derrota al Acechador del Hielo, al señor de la guerra Tzogvin, al protector de la cámara, a Rizzuk el Escalofriante y al guardián de la tablilla en la Cripta Helada (Veterano) en menos de 30 minutos. El temporizador comienza cuando entras en combate.",
["name"] = "Golpear y agarrar",
}
,
[2264] = {
["description"] = "Derrota al Acechador del Hielo, al señor de la guerra Tzogvin, al protector de la cámara, a Rizzuk el Escalofriante y al guardián de la tablilla en la Cripta Helada (Veterano) sin que ningún miembro de tu grupo muera.",
["name"] = "Custodia",
}
,
[2266] = {
["description"] = "Completa los siguientes logros en la Cripta Helada (Veterano).",
["name"] = "Contendiente de la Cripta Helada",
}
,
[2267] = {
["description"] = "Vence en todos los encuentros y derrota al Acechador del Hielo, al señor de la guerra Tzogvin, al protector de la cámara, a Rizzuk el Escalofriante y al guardián de la tablilla tras usar el verificador de veracidad en la Cripta Helada (Veterano) en menos de 30 minutos sin que ningún miembro del grupo muera. El temporizador comienza al entablar combate con el primer grupo de enemigos.",
["name"] = "Asaltante infatigable",
}
,
[2270] = {
["description"] = "Derrota a Fauces Carroñeras, a la Llorona, al orbe oscuro, al rey Narilmor y a la Sinfonía de Espadas en las profundidades de Malatar.",
["name"] = "Vencedor de las profundidades de Malatar",
}
,
[2271] = {
["description"] = "Derrota a Fauces Carroñeras, a la Llorona, al orbe oscuro, al rey Narilmor y a la Sinfonía de Espadas en las profundidades de Malatar (Veterano).",
["name"] = "Conquistador de las profundidades de Malatar",
}
,
[2272] = {
["description"] = "Derrota a la Sinfonía de Espadas después de haber destruido los Dictados de la Dama de la Luz en las profundidades de Malatar (Veterano).",
["name"] = "Sombra proyectada",
}
,
[2273] = {
["description"] = "Derrota a la Fauces Carroñeras, a la Llorona, al orbe oscuro, al rey Narilmor y a la Sinfonía de Espadas en las profundidades de Malatar (Veterano) en menos de 30 minutos. El temporizador comienza cuando entras en combate.",
["name"] = "A la velocidad de la luz",
}
,
[2274] = {
["description"] = "Derrota a las Fauces Carroñeras, a la Llorona, al orbe oscuro, al rey Narilmor y a la Sinfonía de Espadas en las profundidades de Malatar (Veterano) sin que ningún miembro de tu grupo muera.",
["name"] = "Purificación",
}
,
[2275] = {
["description"] = "Completa los siguientes logros en las profundidades de Malatar (Veterano).",
["name"] = "Contendiente de las profundidades de Malatar",
}
,
[2276] = {
["description"] = "Derrota a Fauces Carroñeras, a la Llorona, al orbe oscuro, al rey Narilmor y a Sinfonía de Espadas tras destruir los Dictados de la Dama de la Luz en las profundidades de Malatar (Veterano) en menos de 30 minutos sin que ningún miembro del grupo muera. El temporizador comienza al entablar combate con el primer grupo de enemigos.",
["name"] = "Profanador de las profundidades",
}
,
[2277] = {
["description"] = "Completa la Cripta Helada y las profundidades de Malatar en modo Veterano.",
["name"] = "Espeleólogo de Wrathstone",
}
,
[2292] = {
["description"] = "Derrota a los dos jefes de mundo en Lodazal Lóbrego.",
["name"] = "Defensor de Lodazal Lóbrego",
}
,
[2293] = {
["description"] = "Derrota al nigromante Baxilt-Gah en Bok-Xul.",
["name"] = "Monstruo del pantano",
}
,
[2294] = {
["description"] = "Derrota al miregaunt Pasos De Trueno en la Cuenca del Eco.",
["name"] = "Verdugo del trueno",
}
,
[2297] = {
["description"] = "Derrota a Mylenne Aúlla Lunas sin purificar su habilidad Encolerizar en el Bastión del Cazador de la Luna (Veterano).",
["name"] = "Ira interminable",
}
,
[2298] = {
["description"] = "Derrota al archivista Ernarde sin matar a su primer aliado hombre lobo descomunal en el Bastión del Cazador de la Luna.",
["name"] = "Un aliado poderoso",
}
,
[2299] = {
["description"] = "Derrota al archivista sin que ningún miembro del grupo sufra daño por los Símbolos de Xarxes en el Bastión del Cazador de la Luna.",
["name"] = "Amante de la literatura",
}
,
[2300] = {
["description"] = "Derrota a Vykosa la Ascendida sin que ningún miembro del grupo reciba daño de su lobo mascota retenido en el Bastión del Cazador de la Luna (Veterano).",
["name"] = "Atado en corto",
}
,
[2301] = {
["description"] = "Derrota a Vykosa la Ascendida en el Bastión del Cazador de la Luna (Veterano) tras invocar el pergamino de la gloriosa batalla, derrotar siete estranguladoras y sin causar que sus lobos mascota se atemoricen.",
["name"] = "Cobardía estranguladora",
}
,
[2302] = {
["description"] = "Completa las tres cazas del indrik dorado y obtén sus bendiciones en la Marcha de los Sacrificios.",
["name"] = "La gran cacería del indrik",
}
,
[2303] = {
["description"] = "Derrota a Aghaedh del Solsticio asegurándote de derrotar a cada una de sus moles arbóreas en sus respectivas estaciones primarias en la Marcha de los Sacrificios (Veterano).",
["name"] = "Muerte estacional",
}
,
[2304] = {
["description"] = "Derrota a Dagrund el Rechoncho mientras esquivas siempre su habilidad Agitación en la Marcha de los Sacrificios (Veterano).",
["name"] = "Pies ligeros",
}
,
[2305] = {
["description"] = "Derrota a Tarcyr sin que el indrik teleporte a ningún miembro del grupo durante la habilidad Niebla envolvente en las Marcha de los Sacrificios (Veterano).",
["name"] = "Caminante de la niebla",
}
,
[2306] = {
["description"] = "Lleva a Balorgh a la trampa de Tharas 10 veces en la Marcha de los Sacrificios.",
["name"] = "Truco y trampa",
}
,
[2307] = {
["description"] = "Derrota al carcelero Melito sin sufrir daño de los géiseres de sangre en el Bastión del Cazador de la Luna.",
["name"] = "Desastre sangriento",
}
,
[2308] = {
["description"] = "Derrota al guardián del laberinto sin que ningún miembro del grupo quede atrapado en una trampa estranguladora en los jardines del Bastión del Cazador de la Luna (Veterano).",
["name"] = "Esquivando estranguladoras",
}
,
[2309] = {
["description"] = "Derrota al guardián del laberinto mientras todos los miembros del grupo evitan su ataque Raíces de mole arbórea en el Bastión del Cazador de la Luna (Veterano).",
["name"] = "La raíz de los problemas",
}
,
[2310] = {
["description"] = "Derrota a las hermanas del wyrd mientras evitas que usen sus auras para fortalecerse entre ellas en la Marcha de los Sacrificios (Veterano).",
["name"] = "Hermanas ante todo",
}
,
[2311] = {
["description"] = "Derrota a Balorgh evitando tanto el agua electrificada como las plantas venenosas en la Marcha de los Sacrificios (Veterano).",
["name"] = "Factor sorpresa",
}
,
[2312] = {
["description"] = "Derrota a Balorgh después de profanar el estandarte de la Manada del Cazador de la Luna y sin sufrir daño de su habilidad Remanente de fuego durante todo el combate en la Marcha de los Sacrificios (Veterano).",
["name"] = "Una caza perfecta",
}
,
[2321] = {
["description"] = "Derrota a los cuatro miregaunt que se han tragado las tablillas del Xinchei-Konu.",
["name"] = "Quienes se tragan las estaciones",
}
,
[2330] = {
["description"] = "Conoce a los escama sombría que tienen un peculiar interés en tus actividades en Lodazal Lóbrego.",
["name"] = "Sombra discreta",
}
,
[2331] = {
