}
,
[2364] = {
["description"] = "Derrota a la maga guerrera Ennodio, a Doma Las Bestias, a lady Minara y a Drakeeh el Desencadenado en la Prisión de Rosa Negra (Veterano) sin usar los sellos durante el combate.",
["name"] = "Austero con los sellos",
}
,
[2365] = {
["description"] = "Derrota a la maga guerrera Ennodio, a Doma Las Bestias, a lady Minara y a Drakeeh el Desencadenado en la Prisión de Rosa Negra (Veterano) sin morir.",
["name"] = "Desencadenado y eterno",
}
,
[2366] = {
["description"] = "Derrota a la maga guerrera Ennodio, a Doma Las Bestias, a lady Minara y a Drakeeh el Desencadenado en la Prisión de Rosa Negra (Veterano) en menos de 30 minutos. El temporizador se iniciará cuando dé comienzo la primera arena.",
["name"] = "Desafío al galope",
}
,
[2367] = {
["description"] = "Derrota a la maga guerrera Ennodio, a Doma Las Bestias, a lady Minara y a Drakeeh el Desencadenado en la Prisión de Rosa Negra (Veterano) en menos de 40 minutos sin morir. El temporizador se iniciará cuando dé comienzo la primera arena.",
["name"] = "Bucanero de Rosa Negra",
}
,
[2368] = {
["description"] = "Derrota a la maga guerrera Ennodio, a Doma Las Bestias, a lady Minara y a Drakeeh el Desencadenado en la Prisión de Rosa Negra (Veterano) en menos de 40 minutos sin morir y sin activar los sellos durante el combate. El temporizador se iniciará cuando dé comienzo la primera arena.",
["name"] = "Dios del desafío",
}
,
[2369] = {
["description"] = "Derrota a la maga guerrera Ennodio sin que ningún miembro del grupo sufra daño de fuego mientras su habilidad Chorro ígneo esté activa en la Prisión de Rosa Negra (Veterano).",
["name"] = "Más veloz que el fuego",
}
,
[2370] = {
["description"] = "Derrota a Doma Las Bestias sin que ningún miembro del grupo se vea atrapado por la habilidad Raíces aplastantes en la Prisión de Rosa Negra (Veterano).",
["name"] = "Desarraigo",
}
,
[2371] = {
["description"] = "Derrota a lady Mirana después que los tres colosos de hueso sean invocados en los primeros 30 segundos de combate en la Prisión de Rosa Negra (Veterano).",
["name"] = "Invocación esquelética",
}
,
[2372] = {
["description"] = "Derrota a la maga guerrera Ennodio, a lady Minara y a Doma Las Bestias con menos de 20 segundos de intervalo entre ellos en la Prisión de Rosa Negra (Veterano).",
["name"] = "Tridente trepidante",
}
,
[2373] = {
["description"] = "Derrota a Drakeeh el Desencadenado mientras te aseguras de que siempre absorba al menos 2 espíritus antes de lanzar Grito Espiritual en la Prisión de Rosa Negra (Veterano).",
["name"] = "Espíritus divididos",
}
,
[2374] = {
["description"] = "Utiliza la habilidad Meteorito de la maga guerrera Ennodio para aturdir a los cuatro atronach a la vez en la primera arena de la Prisión de Rosa Negra.",
["name"] = "Caos de meteoritos",
}
,
[2375] = {
["description"] = "Utiliza un sello de resurrección en cualquier arena para revivir a tres miembros del grupo a la vez en la Prisión de Rosa Negra.",
["name"] = "Alzamiento de los caídos",
}
,
[2376] = {
["description"] = "Haz que un solo miembro del grupo absorba al menos tres objetivos de Drakeeh durante su habilidad Ignición espiritual y que ese miembro se purifique sin morir.",
["name"] = "Purificación de los condenados",
}
,
[2380] = {
["description"] = "Haz que el Acechador del Hielo golpee a sus aliados durante sus Golpetazos frenéticos en la Cripta Helada.",
["name"] = "Paliza salvaje",
}
,
[2381] = {
["description"] = "Esquiva todas las temerarias embestidas del señor de la guerra Tzogvin en la Cripta Helada.",
["name"] = "Encontrando el ángulo correcto",
}
,
[2382] = {
["description"] = "Consigue que el señor de la guerra Tzogvin destruya sus tres estandartes con sus Vientos iracundos en la Cripta Helada.",
["name"] = "Tres velas al viento",
}
,
[2384] = {
["description"] = "Derrota a Rizzuk y a Avalancha en la Cripta Helada después de que cada miembro del grupo haya sido afectado por la habilidad Prisión glacial de Avalancha al menos una vez durante el enfrentamiento en la Cripta Helada (Veterano).",
["name"] = "Pata fría",
}
,
[2385] = {
["description"] = "Haz caer a 20 enemigos de la plataforma del guardián de la tablilla en la Cripta Helada.",
["name"] = "Prueba de gravedad",
}
,
[2386] = {
["description"] = "Toma control de cada tipo de skeevaton modificado. Los skeevaton modificados aparecen durante la fase de protocolo de exterminación del guardián de la tablilla tras haber activado el verificador de veracidad en la Cripta Helada (Veterano). No puedes morir ni convertirte en chatarra hasta el final de la fase si quieres recibir el crédito.",
["name"] = "Una variedad de alimañas",
}
,
[2387] = {
["description"] = "Desactiva el protocolo de exterminio del guardián de la tablilla con los skeevaton de Tharayya en menos de 35 segundos después de haberlos invocado en la Cripta Helada. El temporizador comienza al inicio de su advertencia.",
["name"] = "Carrera de ratas",
}
,
[2388] = {
["description"] = "No permitas que ninguna probóscide de caza de Fauces Carroñeras sea destrozada y no te dejes alcanzar por ninguna de las formas sombrías en las profundidades de Malatar (Veterano).",
["name"] = "Escondite",
}
,
[2389] = {
["description"] = "Ningún miembro del grupo debe recibir daño de Glaciación durante la batalla contra la Llorona en las profundidades de Malatar (Veterano).",
["name"] = "Patinando sobre el hielo",
}
,
[2390] = {
["description"] = "No destruyas ningún orbe coloreado durante el encuentro con el orbe oscuro en las profundidades de Malatar (Veterano).",
["name"] = "Daltonismo",
}
,
[2391] = {
["description"] = "Evita que Quinto gane su duelo con Tharayya durante la batalla contra el rey Narilmor en las profundidades de Malatar.",
["name"] = "Almas gemelas",
}
,
[2392] = {
["description"] = "Derrota a un aurorano de cada color durante la batalla contra la Sinfonía de Espadas en las profundidades de Malatar.",
["name"] = "Cosecha de arcoíris",
}
,
[2393] = {
["description"] = "Evita que la Sinfonía de Espadas atraviese la falange aurorana y se refuerce con la Luz de Meridia en las profundidades de Malatar (Veterano).",
["name"] = "Fuera de formación",
}
,
[2395] = {
["description"] = "Después de leer el Dictado de la Dama de la Luz, entra en la sala coloreada y destruye a todos los orbes coloreados durante el encuentro con Sinfonía de Espadas en las profundidades de Malatar (Veterano).",
["name"] = "Deslustrado",
}
,
[2405] = {
["description"] = "Derrota al guardián del cráneo, Na\'ruzz el Tejedor de Huesos, en la Fosa de los Huesos.",
["name"] = "Destructor de cráneos",
}
,
