[2467] = {
["description"] = "Derrota a Yolnahkriin, a Lokkestiiz y a Nahviintaas junto con todos sus seguidores hostiles tras extinguir sus braseros de ofrendas, sin que ningún miembro del grupo muera y en menos de 30 minutos después de haber entrado en el corredor entre el vestíbulo del Templo de la Cúspide del Sol y el patio en la Cúspide del Sol (Veterano).",
