[2539] = {
["description"] = "Derrota a Kjarg el Rascador de Colmillos, a la hermana Skelga, a Vearogh el Rezagado, al hijo de la tormenta reanimado y al aquelarre de la Cuenca Glacial en Cuenca Glacial.",
