}
,
[2542] = {
["description"] = "Derrota a Kjarg el Rascador de Colmillos, a la hermana Skelga, a Vearogh el Rezagado, al hijo de la tormenta reanimado y al aquelarre de la Cuenca Glacial en menos de 30 minutos tras acceder a la Cuenca Glacial (Veterano). El temporizador comienza al entablar combate con el primer grupo de enemigos.",
["name"] = "Prisa del thane",
}
,
[2543] = {
["description"] = "Vence en todos los encuentros además de derrotar a Kjarg el Rascador de Colmillos, a la hermana Skelga, a Vearogh el Rezagado, al hijo de la tormenta reanimado y al aquelarre de la Cuenca Glacial en Cuenca Glacial (Veterano) sin que ningún miembro de tu grupo muera.",
