,
[2546] = {
["description"] = "Vence en todos los encuentros y derrota a Kjarg el Rascador de Colmillos, a la hermana Skelga, a Vearogh el Rezagado, al hijo de la tormenta reanimado y al aquelarre de la Cuenca Glacial tras quemar el tótem de mimbre de las brujas en la Cuenca Glacial (Veterano) en menos de 30 minutos sin que ningún miembro del grupo muera. El temporizador comienza al entablar combate con el primer grupo de enemigos.",
["name"] = "No hay descanso para los malvados",
}
,
[2549] = {
