,
[2552] = {
["description"] = "Vence en todos los encuentros y derrota además a Hakgrym el Aullador, al guardián del Horno, a la égida eterna a Ondagore el Demente y a Kjalnar Escaldo Fúnebre en el Sepulcro Profano (Veterano) en menos de 30 minutos. El temporizador comienza al entablar combate con el primer grupo de enemigos. No es necesario acceder al sagrario de Voria.",
