,
[2553] = {
["description"] = "Vence en todos los encuentros y derrota además a Hakgrym el Aullador, al guardián del Horno, a la égida eterna, a Ondagore el Demente y a Kjalnar Escaldo Fúnebre en el Sepulcro Profano (Veterano) sin que ningún miembro de tu grupo muera. No es necesario acceder al sagrario de Voria.",
