}
,
[2555] = {
["description"] = "Vence en todos los encuentros y derrota a Hakgrym el Aullador, al guardián del Horno, a la égida eterna, a Ondagore el Demente y a Kjalnar Escaldo Fúnebre tras destruir su tótem impío en el Sepulcro Profano (Veterano) en menos de 30 minutos sin que ningún miembro del grupo muera. No es necesario acceder al sagrario de Voria. El temporizador comienza al entablar combate con el primer grupo de enemigos.",
