}
,
[2695] = {
["description"] = "Derrota al exarca Kraglen, al behemot de piedra y a Arkasis el Alquimista Loco en el Jardín de Piedra (Veterano).",
["name"] = "Conquistador del Jardín de Piedra",
}
,
[2697] = {
["description"] = "Consigue la victoria en todos los encuentros y derrota al exarca Kraglen, al behemot de piedra y a Arkasis el Alquimista Loco en el Jardín de Piedra (Veterano) en menos de 25 minutos. El temporizador comienza cuando los jugadores atacan al primer grupo de defensores del Jardín de Piedra. No es necesario acceder a las salas de control del vitalizador.",
["name"] = "Experimentador expeditivo",
}
,
[2698] = {
["description"] = "Consigue la victoria en todos los encuentros y derrota al exarca Kraglen, al behemot de piedra y a Arkasis el Alquimista Loco en el Jardín de Piedra (Veterano) sin que ningún miembro de tu grupo muera. No es necesario acceder a las salas de control del vitalizador.",
["name"] = "¡Seguridad ante todo!",
