}
,
[2701] = {
["description"] = "Vence en todos los encuentros y derrota al exarca Kraglen, al behemot de piedra y a Arkasis el Alquimista Loco tras izar el estandarte del desafío ante cada uno de ellos en el Jardín de Piedra (Veterano) en menos de 25 minutos sin que ningún miembro del grupo muera. No es necesario acceder a las salas de control del vitalizador. El temporizador comienza al entablar combate con el primer grupo de enemigos.",
